from math import pi, fabs


class TriCalculator:

    DEGREES_TO_RADIANS_FACTOR = pi / 180
    CONVERGENCE_TEST_TOLERANCE = 1e-15
    RADIANS_PER_DEGREE = pi / 180

    def __init__(self):
        pass

    def cos(self, x):
        return round(self.taylor(x, 50), 10)

    def factorial(self, a):
        b = 1
        while a != 1:
            b *= a
            a -= 1
        return b

    def taylor(self, x, n):
        radians = self.degrees_to_radians(x)
        a = 1
        count = 1
        for k in range(1, n):
            if count % 2 != 0:
                a -= self.cos_term(radians, k)
            else:
                a += self.cos_term(radians, k)
            count += 1
        return a

    def cos_term(self, radians, k):
        return (radians ** (2 * k)) / self.factorial(2 * k)

    def sin(self, x):
        radians = self.degrees_to_radians(x)
        g = 0
        t = radians
        n = 1

        while fabs(t) >= self.CONVERGENCE_TEST_TOLERANCE:
            g += t
            n += 1
            t = -t * radians * radians / (2 * n - 1) / (2 * n - 2)
        return round(g, 10)

    def tan(self, x):
        if self.cos(x) != 0:
            result = self.sin(x) / self.cos(x)
            return round(result, 10)
        else:
            return False

    @staticmethod
    def degrees_to_radians(degrees):
        return degrees * (pi / 180)
